import struct
import hashlib
import hmac
import os
import time
from flask import Flask, request, jsonify, abort
import sqlite3

app = Flask(__name__)
SECRET_KEY = os.environ.get('SECRET_KEY', os.urandom(32))
DB_PATH = '/var/app/data.db'

PBKDF2_ITERATIONS = 200000


def hash_password(password: str, salt: bytes = None) -> str:
    if salt is None:
        salt = os.urandom(16)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, PBKDF2_ITERATIONS)
    return salt.hex() + '$' + dk.hex()


def verify_password(password: str, stored: str) -> bool:
    if not stored or '$' not in stored:
        return False
    try:
        salt_hex, dk_hex = stored.split('$', 1)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(dk_hex)
    except (ValueError, TypeError):
        return False
    dk = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, PBKDF2_ITERATIONS)
    return hmac.compare_digest(dk, expected)


def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_db()
    conn.execute('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT UNIQUE, role TEXT, data TEXT, password_hash TEXT)')
    conn.execute('CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY, action TEXT, ts REAL)')
    conn.commit()
    conn.close()

class TokenManager:
    """Custom binary token format:
    [4 bytes: user_id (big-endian unsigned int32)]
    [4 bytes: issued_at (big-endian unsigned int32)]
    [4 bytes: expires_at (big-endian unsigned int32)]
    [1 byte: role_code]
    [32 bytes: HMAC-SHA256 signature]
    Total: 45 bytes
    """
    ROLE_USER = 0x01
    ROLE_ADMIN = 0x02
    TOKEN_LIFETIME = 3600
    MAX_USER_ID = 2147483647  # INT32_MAX

    @staticmethod
    def create_token(user_id: int, role_code: int) -> bytes:
        if user_id <= 0 or user_id > TokenManager.MAX_USER_ID:
            raise ValueError("Invalid user_id for token creation")
        if role_code not in (TokenManager.ROLE_USER, TokenManager.ROLE_ADMIN):
            raise ValueError("Invalid role_code")
        now = int(time.time())
        expires = now + TokenManager.TOKEN_LIFETIME
        # Pack token payload - user_id as unsigned since we validated > 0
        payload = struct.pack('>IIIB', user_id, now & 0xFFFFFFFF, expires & 0xFFFFFFFF, role_code)
        # Sign with HMAC
        sig = hmac.new(SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(), payload, hashlib.sha256).digest()
        return payload + sig

    @staticmethod
    def validate_token(token_bytes: bytes) -> dict:
        if len(token_bytes) != 45:
            raise ValueError("Invalid token length")

        payload = token_bytes[:13]
        provided_sig = token_bytes[13:]

        # Verify HMAC signature
        expected_sig = hmac.new(SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(), payload, hashlib.sha256).digest()
        if not hmac.compare_digest(provided_sig, expected_sig):
            raise ValueError("Invalid signature")

        # Unpack fields - unsigned int32 for user_id
        user_id, issued_at, expires_at, role_code = struct.unpack('>IIIB', payload)

        # Validate expiration
        now = int(time.time())
        if now > expires_at:
            raise ValueError("Token expired")

        # Validate user_id range - must be positive
        if user_id == 0 or user_id > TokenManager.MAX_USER_ID:
            raise ValueError("Invalid user ID")

        # Validate role_code
        if role_code not in (TokenManager.ROLE_USER, TokenManager.ROLE_ADMIN):
            raise ValueError("Invalid role code in token")

        return {
            'user_id': user_id,
            'issued_at': issued_at,
            'expires_at': expires_at,
            'role_code': role_code
        }

def require_auth(f):
    """Decorator that validates token and attaches user info to request."""
    from functools import wraps
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            abort(401)
        try:
            import base64
            token_bytes = base64.b64decode(auth_header[7:])
            token_data = TokenManager.validate_token(token_bytes)
        except Exception:
            abort(401)
        request.token_data = token_data
        return f(*args, **kwargs)
    return decorated

def require_admin(f):
    """Decorator that checks admin role after auth."""
    from functools import wraps
    @wraps(f)
    def decorated(*args, **kwargs):
        token_data = request.token_data
        # Only role_code determines admin access - no other fallback
        if token_data['role_code'] != TokenManager.ROLE_ADMIN:
            abort(403)
        return f(*args, **kwargs)
    return decorated

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json(silent=True) or {}
    username = data.get('username', '')
    password = data.get('password', '')

    if not username or not password:
        abort(401)

    conn = get_db()
    user = conn.execute('SELECT id, username, role, password_hash FROM users WHERE username = ?', (username,)).fetchone()
    conn.close()

    if not user:
        # Perform a dummy verification to reduce user-enumeration timing signal
        verify_password(password, hash_password(os.urandom(16).hex()))
        abort(401)

    # Verify the supplied password against the stored PBKDF2 hash
    if not verify_password(password, user['password_hash']):
        abort(401)

    role_code = TokenManager.ROLE_ADMIN if user['role'] == 'admin' else TokenManager.ROLE_USER
    token = TokenManager.create_token(user['id'], role_code)

    import base64
    return jsonify({'token': base64.b64encode(token).decode()})

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    token_data = request.token_data
    conn = get_db()
    user = conn.execute('SELECT id, username, role, data FROM users WHERE id = ?', (token_data['user_id'],)).fetchone()
    conn.close()
    if not user:
        abort(404)
    return jsonify(dict(user))

@app.route('/api/admin/users', methods=['GET'])
@require_auth
@require_admin
def admin_list_users():
    conn = get_db()
    users = conn.execute('SELECT id, username, role FROM users').fetchall()
    conn.close()
    return jsonify([dict(u) for u in users])

@app.route('/api/admin/delete_user/<int:target_id>', methods=['DELETE'])
@require_auth
@require_admin
def admin_delete_user(target_id):
    conn = get_db()
    conn.execute('DELETE FROM users WHERE id = ?', (target_id,))
    conn.execute('INSERT INTO audit_log (action, ts) VALUES (?, ?)',
                 (f'delete_user:{target_id}', time.time()))
    conn.commit()
    conn.close()
    return jsonify({'status': 'deleted'})

if __name__ == '__main__':
    init_db()
    app.run(host='127.0.0.1', port=8080)
